/**
 * Validates all fields in BootstrapConfig according to their annotations.
 * @throws {BlueErr} if validation fails
 */
export function validateBootstrapConfig(m: BootstrapConfig | undefined): void {
  if (!m) {
    return;
  }

  // Validate endpoints (assert_listen_addr)
  if (m.endpoints) {
    const listenAddrRegex = /^[^:]+:\d+$/;
    if (!listenAddrRegex.test(m.endpoints)) {
      throw newErrMissingInvalidData(
        undefined,
        `field endpoints must be in host:port format`,
      );
    }
  }

  // Validate instanceId (default max size: 32768 bytes)
  if (m.instanceId && new TextEncoder().encode(m.instanceId).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field instanceId exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.instanceId).length}`,
    );
  }
}
/**
 * Validates all fields in Config according to their annotations.
 * @throws {BlueErr} if validation fails
 */
export function validateConfig(m: Config | undefined): void {
  if (!m) {
    return;
  }

  // Validate listenAddress (assert_listen_addr)
  if (m.listenAddress) {
    const listenAddrRegex = /^[^:]+:\d+$/;
    if (!listenAddrRegex.test(m.listenAddress)) {
      throw newErrMissingInvalidData(
        undefined,
        `field listenAddress must be in host:port format`,
      );
    }
  }

  // Validate maxRequestSize (assert_gt: 0)
  if (m.maxRequestSize !== undefined && m.maxRequestSize <= 0) {
    throw newErrMissingInvalidData(
      undefined,
      `field maxRequestSize must be > 0, got: ${m.maxRequestSize}`,
    );
  }

  // Validate requestTimeoutSeconds (assert_duration: POSITIVE)
  if (m.requestTimeoutSeconds !== undefined && m.requestTimeoutSeconds <= 0) {
    throw newErrMissingInvalidData(
      undefined,
      `field requestTimeoutSeconds must be positive (> 0), got: ${m.requestTimeoutSeconds}`,
    );
  }

  // Validate shutdownTimeoutSeconds (assert_duration: POSITIVE)
  if (m.shutdownTimeoutSeconds !== undefined && m.shutdownTimeoutSeconds <= 0) {
    throw newErrMissingInvalidData(
      undefined,
      `field shutdownTimeoutSeconds must be positive (> 0), got: ${m.shutdownTimeoutSeconds}`,
    );
  }

  // Validate listenAddress (default max size: 32768 bytes)
  if (
    m.listenAddress &&
    new TextEncoder().encode(m.listenAddress).length > 32768
  ) {
    throw newErrMissingInvalidData(
      undefined,
      `field listenAddress exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.listenAddress).length}`,
    );
  }
}
