// ============================================================
/** * Applies default values to Config fields that are at their zero value. */
export function configDefaults(m: Config): void {
  if (m.pingIntervalMs === 0) {
    m.pingIntervalMs = DEFAULT_PING_INTERVAL_MS;
  }
  if (m.rebalanceIntervalMs === 0) {
    m.rebalanceIntervalMs = DEFAULT_REBALANCE_INTERVAL_MS;
  }
  if (m.maxRequestSize === 0n) {
    m.maxRequestSize = DEFAULT_MAX_REQUEST_SIZE;
  }
  if (m.requestTimeoutSeconds === 0n) {
    m.requestTimeoutSeconds = DEFAULT_REQUEST_TIMEOUT_SECONDS;
  }
  if (m.shutdownTimeoutSeconds === 0n) {
    m.shutdownTimeoutSeconds = DEFAULT_SHUTDOWN_TIMEOUT_SECONDS;
  }
}
// ============================================================
// Type Undefaults
// ============================================================
/** Resets Config fields that match defaults back to zero for minimal persistence. */
export function configUndefaults(m: Config): void {
  if (m.pingIntervalMs === DEFAULT_PING_INTERVAL_MS) {
    m.pingIntervalMs = 0;
  }
  if (m.rebalanceIntervalMs === DEFAULT_REBALANCE_INTERVAL_MS) {
    m.rebalanceIntervalMs = 0;
  }
  if (m.maxRequestSize === BigInt(DEFAULT_MAX_REQUEST_SIZE)) {
    m.maxRequestSize = 0n;
  }
  if (m.requestTimeoutSeconds === BigInt(DEFAULT_REQUEST_TIMEOUT_SECONDS)) {
    m.requestTimeoutSeconds = 0n;
  }
  if (m.shutdownTimeoutSeconds === BigInt(DEFAULT_SHUTDOWN_TIMEOUT_SECONDS)) {
    m.shutdownTimeoutSeconds = 0n;
  }
}

// ============================================================
// Merge: BootstrapConfig
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeBootstrapConfig(
  dst: BootstrapConfig,
  src: BootstrapConfig,
): void {
  if (dst.endpoints.length === 0) {
    dst.endpoints = src.endpoints;
  }
  if (dst.instanceId === "") {
    dst.instanceId = src.instanceId;
  }
  if (!dst.privateKey && src.privateKey) {
    dst.privateKey = src.privateKey;
  }
  if (dst.trustedCas.length === 0) {
    dst.trustedCas = src.trustedCas;
  }
}
